/* Phase controls and meaningful lesson navigation. */
(()=>{
 const phasesInfo=[['Find your starting point.','Turn the things you notice into a question worth exploring.','Explore foundations'],['See the connections.','Bring sources together. Discover what is known and what is still missing.','Explore discovery'],['Shape what comes next.','Connect your question, evidence, and methods in a proposal with purpose.','Explore creation']];
 document.addEventListener('click',e=>{const b=e.target.closest('[data-atlas]');if(!b)return;const phase=Number(b.dataset.atlas),stage=b.closest('.discovery-stage');stage.dataset.phase=phase;stage.querySelectorAll('[data-atlas]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));document.querySelector('#atlas-title').textContent=phasesInfo[phase][0];document.querySelector('#atlas-description').textContent=phasesInfo[phase][1];const a=document.querySelector('#atlas-link');a.innerHTML=phasesInfo[phase][2]+' '+icon('up');a.href='#lesson/'+phase*3;window.dispatchEvent(new CustomEvent('rrh:phase',{detail:{phase}}));if(document.documentElement.dataset.motion!=='off'){for(const el of [document.querySelector('#atlas-title'),document.querySelector('#atlas-description')])el.animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:500,easing:'cubic-bezier(.16,1,.3,1)'})}});
 function setup(){const title=document.querySelector('.lesson-title');if(!title)return;if(document.querySelector('.lesson-flow'))return;const n=Number(location.hash.split('/')[1]||0);title.insertAdjacentHTML('afterbegin','<span class="lesson-watermark" aria-hidden="true">'+String(n+1).padStart(2,'0')+'</span>');const content=document.querySelector('.lesson-content');if(!content)return;const heads=[...content.querySelectorAll('h2')];heads.forEach((h,i)=>{h.id='lesson-section-'+i;h.insertAdjacentHTML('afterbegin','<span class="chapter-index" aria-hidden="true">'+String(i+1).padStart(2,'0')+'</span>')});const nav=document.createElement('nav');nav.className='lesson-chapters';nav.setAttribute('aria-label','On this page');nav.innerHTML='<span>IN THIS LESSON</span>'+heads.map((h,i)=>'<button data-chapter="lesson-section-'+i+'">'+esc(h.textContent.slice(2))+'</button>').join('')+'<button data-chapter="exercise-text">Your exercise '+icon('arrow')+'</button>';title.after(nav);nav.addEventListener('click',e=>{const b=e.target.closest('[data-chapter]');if(!b)return;const target=document.getElementById(b.dataset.chapter);if(target){target.scrollIntoView({behavior:document.documentElement.dataset.motion==='off'?'instant':'smooth',block:'center'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true})}})}
 window.addEventListener('rrh:route',setup);setup();
})();
